import Joi from "joi";

/**
 * Create Material Master Validation
 */
export const createMaterialMasterValidation = Joi.object({
  // materialCode is auto-generated by the system
  materialName: Joi.string().trim().min(2).max(100).required().messages({
    "string.empty": "Material Name is required.",
    "string.min": "Material Name must be at least 2 characters.",
    "string.max": "Material Name cannot exceed 100 characters.",
    "any.required": "Material Name is required.",
  }),

  categoryId: Joi.string().length(24).hex().required().messages({
    "string.empty": "Category is required.",
    "string.length": "Invalid Category ID.",
    "string.hex": "Invalid Category ID.",
    "any.required": "Category is required.",
  }),

  subCategoryId: Joi.string().length(24).hex().required().messages({
    "string.empty": "Sub Category is required.",
    "string.length": "Invalid Sub Category ID.",
    "string.hex": "Invalid Sub Category ID.",
    "any.required": "Sub Category is required.",
  }),

  uomId: Joi.string().length(24).hex().required().messages({
    "string.empty": "Unit of Measure is required.",
    "string.length": "Invalid UOM ID.",
    "string.hex": "Invalid UOM ID.",
    "any.required": "Unit of Measure is required.",
  }),

  materialType: Joi.string()
    .valid(
      "Raw Material",
      "Consumable",
      "Packaging",
      "Semi Finished",
      "Finished Good"
    )
    .required()
    .messages({
      "any.only": "Invalid Material Type.",
      "any.required": "Material Type is required.",
    }),

  minimumStock: Joi.number().min(0).required().messages({
    "number.base": "Minimum Stock must be a number.",
    "number.min": "Minimum Stock cannot be negative.",
    "any.required": "Minimum Stock is required.",
  }),

  maximumStock: Joi.number().min(0).optional().messages({
    "number.base": "Maximum Stock must be a number.",
    "number.min": "Maximum Stock cannot be negative.",
  }),

  reorderLevel: Joi.number().min(0).required().messages({
    "number.base": "Reorder Level must be a number.",
    "number.min": "Reorder Level cannot be negative.",
    "any.required": "Reorder Level is required.",
  }),

  openingStock: Joi.number().min(0).optional().messages({
    "number.base": "Opening Stock must be a number.",
    "number.min": "Opening Stock cannot be negative.",
  }),

  hsnCode: Joi.string().trim().max(20).allow("").optional().messages({
    "string.max": "HSN Code cannot exceed 20 characters.",
  }),

  gstRate: Joi.number().min(0).max(100).optional().messages({
    "number.base": "GST Rate must be a number.",
    "number.min": "GST Rate cannot be less than 0.",
    "number.max": "GST Rate cannot exceed 100.",
  }),

  image: Joi.string().trim().allow("").optional().messages({
    "string.base": "Image must be a string.",
  }),

  description: Joi.string().trim().max(500).allow("").optional().messages({
    "string.max": "Description cannot exceed 500 characters.",
  }),

  displayOrder: Joi.number().min(0).optional().messages({
    "number.base": "Display Order must be a number.",
    "number.min": "Display Order cannot be negative.",
  }),
});

/**
 * Update Material Master Validation
 */
export const updateMaterialMasterValidation = Joi.object({
  materialName: Joi.string().trim().min(2).max(100),

  categoryId: Joi.string().length(24).hex(),

  subCategoryId: Joi.string().length(24).hex(),

  uomId: Joi.string().length(24).hex(),

  materialType: Joi.string().valid(
    "Raw Material",
    "Consumable",
    "Packaging",
    "Semi Finished",
    "Finished Good"
  ),

  minimumStock: Joi.number().min(0),

  maximumStock: Joi.number().min(0),

  reorderLevel: Joi.number().min(0),

  openingStock: Joi.number().min(0),

  hsnCode: Joi.string().trim().max(20).allow(""),

  gstRate: Joi.number().min(0).max(100),

  image: Joi.string().trim().allow(""),

  description: Joi.string().trim().max(500).allow(""),

  displayOrder: Joi.number().min(0),

  isActive: Joi.boolean(),
});

/**
 * Material Master ID Validation
 */
export const materialMasterIdValidation = Joi.object({
  id: Joi.string().length(24).hex().required().messages({
    "string.empty": "Material ID is required.",
    "string.length": "Invalid Material ID.",
    "string.hex": "Invalid Material ID.",
    "any.required": "Material ID is required.",
  }),
});

/**
 * Material Master Search Validation
 */
export const materialMasterSearchValidation = Joi.object({
  materialCode: Joi.string().trim(),

  materialName: Joi.string().trim(),

  categoryId: Joi.string().length(24).hex(),

  subCategoryId: Joi.string().length(24).hex(),

  materialType: Joi.string().valid(
    "Raw Material",
    "Consumable",
    "Packaging",
    "Semi Finished",
    "Finished Good"
  ),

  isActive: Joi.boolean(),
});